import { readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import { recordOf } from "./model";
import { getCompanies, repoRoot } from "./repository";

// companies/<slug>/screens/: screens.json (config + inventory, written by agents), latest.json (generated by
// tools/screens.py sync) and notes.json (per-screen notes with revisions). Captures are PNGs on disk.
export type Surface = {
  id: string;
  title: string;
  feature: string;
  featureTitle: string;
  route?: string;
  source?: string;
  states: string[];
  gap?: string;
};
export type Frame = { image: string; run: string; finished: string; capture?: string; config: Record<string, string> };
export type Captured = { surface: string; known: boolean; frames: Record<string, Frame>; updated: string };
export type Note = {
  id: string;
  surface: string;
  severity: "issue" | "needs-evaluation" | "suggestion";
  status: "open" | "resolved";
  revisions: { at: string; author: string; text: string; capture?: string | null }[];
};
export type ProjectScreens = {
  slug: string;
  adapter: string;
  review?: string;
  features: { id: string; title: string; surfaces: Surface[] }[];
  latest: Record<string, Captured>;
  runs: { run: string; status: string; finished: string; captures: number; config: Record<string, string> }[];
  notes: Note[];
  allowedRoots: string[];
};

async function json(file: string): Promise<Record<string, unknown> | undefined> {
  try {
    return recordOf(JSON.parse(await readFile(file, "utf8")));
  } catch {
    return undefined;
  }
}
const list = (v: unknown) => (Array.isArray(v) ? v : []);
const text = (v: unknown) => (typeof v === "string" ? v : "");

export const getScreens = cache(async (slug: string): Promise<ProjectScreens | undefined> => {
  if (!/^[a-z0-9-]+$/.test(slug)) return undefined;
  const dir = path.join(repoRoot, "companies", slug, "screens");
  const shared = await json(path.join(dir, "screens.json"));
  if (!shared) return undefined;
  // Commands and outside paths only come from capture.json, which agents can't write (see tools/screens.py).
  const trusted = (await json(path.join(dir, "capture.json"))) || {};
  const config = {
    ...Object.fromEntries(Object.entries(shared).filter(([k]) => k !== "delegate" && k !== "inventory_file")),
    ...Object.fromEntries(Object.entries(trusted).filter(([k]) => ["adapter", "delegate", "inventory_file"].includes(k))),
  } as Record<string, unknown>;
  const raw = [...list(config.inventory)];
  if (text(config.inventory_file)) raw.push(...list((await json(text(config.inventory_file)))?.features));
  const features = raw.map((f) => {
    const feature = recordOf(f);
    return {
      id: text(feature.id),
      title: text(feature.title) || text(feature.id),
      surfaces: list(feature.surfaces).map((s) => {
        const r = recordOf(s);
        return {
          id: text(r.id),
          title: text(r.title) || text(r.id),
          feature: text(feature.id),
          featureTitle: text(feature.title),
          route: text(r.route) || undefined,
          source: text(r.source) || undefined,
          states: list(r.states).map(String),
          gap: text(r.gap) || undefined,
        };
      }),
    };
  });
  const latest = await json(path.join(dir, "latest.json"));
  const notes = list((await json(path.join(dir, "notes.json")))?.notes) as Note[];
  const delegateRuns = text(recordOf(config.delegate).runs);
  return {
    slug,
    adapter: text(config.adapter),
    review: text(config.review) || undefined,
    features,
    latest: recordOf(latest?.surfaces) as Record<string, Captured>,
    runs: list(latest?.runs) as ProjectScreens["runs"],
    notes,
    allowedRoots: [path.join(dir, "runs"), ...(delegateRuns ? [delegateRuns] : [])],
  };
});

export const getAllScreens = cache(async () => {
  const companies = await getCompanies();
  const all = await Promise.all(companies.map(async (c) => ({ company: c, screens: await getScreens(c.id) })));
  return all;
});

// Only PNGs inside a project's own capture folders are served (resolved through symlinks).
export async function safeImage(slug: string, file: string): Promise<string | undefined> {
  const screens = await getScreens(slug);
  if (!screens || !file.toLowerCase().endsWith(".png")) return undefined;
  try {
    const real = await realpath(file);
    for (const root of screens.allowedRoots) {
      const base = await realpath(root).catch(() => undefined);
      if (base && real.startsWith(base + path.sep)) return real;
    }
  } catch {}
  return undefined;
}

export const imageHref = (slug: string, file: string) =>
  `/screens/image?slug=${encodeURIComponent(slug)}&file=${encodeURIComponent(file)}`;

export const severityLabels: Record<string, string> = {
  issue: "Issue",
  "needs-evaluation": "Needs a look",
  suggestion: "Suggestion",
};
